import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BZO4qERu.js";const y=JSON.parse('{"title":"Data & privacy","description":"","frontmatter":{},"headers":[],"relativePath":"online/privacy.md","filePath":"online/privacy.md","lastUpdated":1793111003000}'),n={name:"online/privacy.md"};function s(i,e,h,c,d,l){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="data-privacy" tabindex="-1">Data &amp; privacy <a class="header-anchor" href="#data-privacy" aria-label="Permalink to &quot;Data &amp; privacy&quot;">​</a></h1><p>How the online edition handles your keys, searches, and history.</p><h2 id="your-saved-keys" tabindex="-1">Your saved keys <a class="header-anchor" href="#your-saved-keys" aria-label="Permalink to &quot;Your saved keys&quot;">​</a></h2><p>Keys you save in Settings are encrypted on the PaperSeek server, used only for your own tasks, and never shown again; the page displays only their last four characters. You can delete all saved keys from <strong>Settings › User</strong> — see <a href="./account">Your account</a>.</p><h2 id="search-without-signing-in" tabindex="-1">Search without signing in <a class="header-anchor" href="#search-without-signing-in" aria-label="Permalink to &quot;Search without signing in&quot;">​</a></h2><p>Without an account you can run a temporary search: choose a provider and model, and type your model key (and a data-source key if the source needs one) directly into the search form. Keys are used for that search only and are never saved, including in the browser.</p><p>A temporary search is held in server memory. You can refresh the tab while it is available, but it is not added to history, and it may be gone after the tab closes, it expires, or the service restarts. Bibliometrics, reviews, history, and Settings require an account. Sign in <strong>before starting</strong> a search you want to keep; signing in later does not import a temporary search.</p><h2 id="your-history" tabindex="-1">Your history <a class="header-anchor" href="#your-history" aria-label="Permalink to &quot;Your history&quot;">​</a></h2><p>Signed-in searches, analyses, and reviews are stored with your account so you can reopen them. You can clear your history from <strong>Settings › User</strong>; clearing stops running tasks first and does not change credit records. Details: <a href="./account">Your account</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./byok">Your own keys</a> — set up and scope of saved keys.</li><li><a href="./../self-hosting/">Self-hosting</a> — keep all data on your own machine with the Community edition.</li></ul>',11)])])}const p=a(n,[["render",s]]);export{y as __pageData,p as default};
